Input: {"question": "When was the South Calgary electoral district created?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0427-6303c6197fbb:d00", "start": 0, "end": 132, "text": "Calgary-South East Calgary-South East (previously styled Calgary South East) is a provincial electoral district in Calgary, Alberta."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0427-6303c6197fbb:d00", "start": 133, "end": 208, "text": "It has existed twice, first from 1959 to 1963, and then re-created in 2010."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0427-6303c6197fbb:d00", "start": 209, "end": 299, "text": "The district is mandated to return a single member to the Legislative Assembly of Alberta."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0427-6303c6197fbb:d00", "start": 300, "end": 412, "text": "The current electoral district was created from a portion of Airdrie-Chestermere, Calgary-Hays and Calgary-Shaw."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0427-6303c6197fbb:d00", "start": 413, "end": 530, "text": "It contains the neighbourhoods of Auburn Bay, Chaparral, Copperfield, Cranston, Mahogany, New Brighton and Silverado."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0427-6303c6197fbb:d00", "start": 531, "end": 687, "text": "The first provincial electoral district to use the name Calgary South East was created in the 1959 redistribution that saw the provincial ridings of Calgary"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0427-6303c6197fbb:d01", "start": 0, "end": 117, "text": "South Calgary (provincial electoral district) South Calgary was a provincial electoral district from Alberta, Canada."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0427-6303c6197fbb:d01", "start": 118, "end": 223, "text": "The electoral district returned a single member to the Legislative Assembly of Alberta from 1913 to 1921."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0427-6303c6197fbb:d01", "start": 224, "end": 306, "text": "After 1921 the district was abolished and reconstituted to a five-member district."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0427-6303c6197fbb:d01", "start": 307, "end": 441, "text": "The South Calgary electoral district was created in 1913 when the Calgary provincial electoral district was carved into three ridings."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0427-6303c6197fbb:d01", "start": 442, "end": 511, "text": "The first election in 1913 featured a two candidate fight between Dr."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0427-6303c6197fbb:d01", "start": 512, "end": 597, "text": "Thomas Blow Conservative candidate and well known Calgary area lawyer Clifford Jones."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0427-6303c6197fbb:d01", "start": 598, "end": 660, "text": "Blow won the district with 71% of the popular vote, riding the"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0427-6303c6197fbb:d02", "start": 0, "end": 162, "text": "Calgary Southeast Calgary Southeast was a federal electoral district in Alberta, Canada, that was represented in the House of Commons of Canada from 1988 to 2015."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0427-6303c6197fbb:d02", "start": 163, "end": 225, "text": "The district was in the southeast part of the City of Calgary."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0427-6303c6197fbb:d02", "start": 226, "end": 282, "text": "It was bounded by the city limits to the south and east."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0427-6303c6197fbb:d02", "start": 283, "end": 381, "text": "The electoral district was created in 1986 from Calgary East, Bow River and Calgary South ridings."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0427-6303c6197fbb:d02", "start": 382, "end": 459, "text": "In 1996, parts were transferred from this electoral district to Calgary East."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0427-6303c6197fbb:d02", "start": 460, "end": 611, "text": "This riding has elected the following Members of Parliament: \"Note: Conservative vote is compared to the total of Progressive Conservative and Canadian"}}, "original_cards": [{"doc_id": "ramdocs-0427-6303c6197fbb:d00", "card_id": "ramdocs-0427-6303c6197fbb:d00:c0", "entity": "South Calgary electoral district", "scope": "first creation", "claim": "The first South Calgary electoral district was created in 1959.", "answer": "1959", "quote": "The first provincial electoral district to use the name Calgary South East was created in the 1959 redistribution that saw the provincial ridings of Calgary", "original_document_number": 1}, {"doc_id": "ramdocs-0427-6303c6197fbb:d00", "card_id": "ramdocs-0427-6303c6197fbb:d00:c1", "entity": "South Calgary electoral district", "scope": "re-creation", "claim": "The South Calgary electoral district was re-created in 2010.", "answer": "2010", "quote": "It has existed twice, first from 1959 to 1963, and then re-created in 2010.", "original_document_number": 1}, {"doc_id": "ramdocs-0427-6303c6197fbb:d01", "card_id": "ramdocs-0427-6303c6197fbb:d01:c0", "entity": "South Calgary electoral district", "scope": "creation", "claim": "The South Calgary electoral district was created in 1913.", "answer": "1913", "quote": "The South Calgary electoral district was created in 1913 when the Calgary provincial electoral district was carved into three ridings.", "original_document_number": 2}, {"doc_id": "ramdocs-0427-6303c6197fbb:d02", "card_id": "ramdocs-0427-6303c6197fbb:d02:c0", "entity": "South Calgary electoral district", "scope": "creation", "claim": "The South Calgary electoral district was created in 1986.", "answer": "1986", "quote": "The electoral district was created in 1986 from Calgary East, Bow River and Calgary South ridings.", "original_document_number": 3}], "current_answers": ["1913", "1959", "2010", "1986"], "candidate_answers": [{"candidate_id": "R0", "answer": "1913", "origin": "initial"}, {"can